#!/usr/bin/env bash
# Writes ~/.ssh/config.d/x0ne.conf (multiplexing for `x0ne-*` aliases only) and
# puts its Include at the TOP of ~/.ssh/config: appended, it fell into the last
# Host block. Checked by scripts/test-setup-ssh-aliases.sh.
set -euo pipefail
ssh_dir="$HOME/.ssh"
conf_d="$ssh_dir/config.d"
mkdir -p "$conf_d" "$ssh_dir/x0ne-cm"
chmod 700 "$ssh_dir" "$conf_d" "$ssh_dir/x0ne-cm"

tmp=$(mktemp "$conf_d/.x0ne.conf.XXXXXX")
cat > "$tmp" <<'CONF'
# Generated by `make setup-ssh-aliases`. Applies to aliases named x0ne-* only.
Host x0ne-*
    ControlMaster auto
    ControlPath ~/.ssh/x0ne-cm/%C
    ControlPersist 30m
    ServerAliveInterval 30
    ServerAliveCountMax 6
CONF
chmod 600 "$tmp"
mv -f "$tmp" "$conf_d/x0ne.conf"

cfg="$ssh_dir/config"
line="Include config.d/x0ne.conf"
[ -e "$cfg" ] || { : > "$cfg"; chmod 600 "$cfg"; }
# Already first among Include/Host/Match lines: nothing to do.
first=$(grep -E '^[[:space:]]*(Include|Host|Match)([[:space:]]|$)' "$cfg" | head -1 || true)
if [ "$first" != "$line" ]; then
    tmp=$(mktemp "$ssh_dir/.config.XXXXXX")
    { printf '%s\n\n' "$line"; grep -vxF "$line" "$cfg" || true; } > "$tmp"
    chmod --reference="$cfg" "$tmp" 2>/dev/null || chmod 600 "$tmp"
    mv -f "$tmp" "$cfg"
    echo "  -> added '$line' at the top of ~/.ssh/config"
fi
echo "  ok ~/.ssh/config.d/x0ne.conf written (ControlMaster auto for Host x0ne-*)"
